import{_ as e,c as p,o as r,ah as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"周易尚氏學 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"周易尚氏學 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/shangshi/028.md","filePath":"classics/shangshi/028.md"}'),i={name:"classics/shangshi/028.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><p>剝候卦。時當九月。陰消陽，柔變剛。雜卦雲剝爛也。蓋陰消陽。柔變剛。皆以漸而及。非猝然為之。有似於樹木老皮之剝落。歸藏作僕。僕與撲通。莊子人間世。蚤蚤（上文）僕緣。僕緣即撲緣。撲擊也。而幽（內雙豕）風八月剝棗。傳剝擊也。是僕與剝義同也。不利有攸往。謂陰不宜再長也。傳曰小人長。陰長則陽消。故往不利。</p><p>彖曰。剝。剝也。柔變剛也。不利有攸往。小人長也。順而止之。觀象也。君子尚消息盈虛。天行也。</p><p>艮為視為觀。象失傳。詳焦氏易詁觀卦即順而止。今一陽在上。下觀群陰。仍觀象也。剝本消卦。然相對者必息。一消一息。一盈一虛。天道循環本如此。不足異也。</p><p>象曰。山附於地。剝。上以厚下安宅。</p><p>上謂上九。坤為厚為下。艮為宅為安。</p><p>初六。剝床以足，蔑貞，兇。</p><p>初震位。故曰足。以及也。周語。太宰以史祝。管子服制。官吏以命士。鹽鐵論大論篇。呻吟槁簡。誦死人之語。則有司不以文學。以義皆同及。剝床以足。即剝床及足也。艮為床。易林比之賁雲。展轉空床。內懷憂傷。以賁艮為床也。剝全體民象。故屢言床。虞翻不知此象。以坤消乾初。成巽為床。而惠棟又謂巽為木。坤西南卦。設木於西南奧。乾人藉之。床之象也。故夫一象之失傳。可使名家易。迂曲至於如此。真可嘆也。蔑釋文雲。荀作滅。象曰滅下。蓋荀之所本。王陶廬雲。蔑滅古通。周語而蔑其人民。文選鄰里相送方山詩。音塵慰寂蔑。注皆作滅。故王注云猶消也。惟滅屬下讀。似難為句。滅說文盡也。剝床以足蔑者。言床足被剝盡也。故卜問兇。虞翻下屬為句。訓為無。謂初失位。故曰蔑貞。謂失正也。然二爻當位。亦曰蔑貞。則不合矣。而清易家多從之。非。</p><p>象曰。剝床以足，以滅下也。</p><p>滅下即釋蔑義。</p><p>六二。剝床以辨，蔑貞兇。</p><p>釋文雲。辨徐音辦具之辦。足上也。馬鄭同。薛虞雲。膝下也。王弼亦云足上。按馬鄭王等似皆以二在初上。故云足上。虞翻謂為指間。王引之讀為騙（左足）。騙（左足）膝頭也。俞越（左木）謂辨通胖。胖脅側也。似皆未安。按周禮天官小宰六日廉辨。注杜子春雲廉辨或作廉端。故賈疏雲經本作廉端。是辨端音近通用。端首也。剝床以端。是剝及床頭也。剝之而盡故貞兇。</p><h3 id="象曰。剝床以辨-未有與也。" tabindex="-1">象曰。剝床以辨，未有與也。 <a class="header-anchor" href="#象曰。剝床以辨-未有與也。" aria-label="Permalink to “象曰。剝床以辨，未有與也。”">​</a></h3><p>未有與。言上無應。</p><p>六三。剝之，無咎。</p><p>釋文一本作剝之無咎。非。按之字。乃從象辭而衍。無者是也。三處五陰之中。獨能從善不黨於上下二陰。故曰失上下。</p><h3 id="象曰。剝之無咎。失上下也。" tabindex="-1">象曰。剝之無咎。失上下也。 <a class="header-anchor" href="#象曰。剝之無咎。失上下也。" aria-label="Permalink to “象曰。剝之無咎。失上下也。”">​</a></h3><p>六四。剝床以膚。兇。</p><p>四艮體。艮為膚。故曰剝床以膚。足辨膚皆指床言。膚猶言床面也。人臥床。身與床切。剝及於是。故言近災。自王肅以膚指人身言。豈知剝及人身。則災及矣。胡得曰近。乃後儒惑之。謂床不能稱膚。王引之謂王弼雲。剝床之足。剝床之辨詳。下文亦可曰剝床之膚乎。夫床既可曰足。曰辨。又何不可稱膚。似皆惑於肅說。故拘泥若是。</p><h3 id="象曰。剝床以膚。切近災也。" tabindex="-1">象曰。剝床以膚。切近災也。 <a class="header-anchor" href="#象曰。剝床以膚。切近災也。" aria-label="Permalink to “象曰。剝床以膚。切近災也。”">​</a></h3><p>六五。貫魚以官人寵。無不利。</p><p>坤為魚象失傳。詳焦氏易估除易林外。後唯郭璞知之。洞林璞筮遷徙。得明夷。曰嗟呼黔黎。時漂異類。桑梓之邦。其為魚乎。明夷上坤為魚。為邦。震為桑梓。故曰桑梓之幫。其為魚乎。剝重坤。故曰貫魚。艮為宮為寵。以宮人寵者。周禮九嬪注云。女御八十一人當九夕。世婦二十七人當三夕。三夫人當一夕。是天子之宮進御。每夜九人或三人。故曰貫魚以宮人寵。言宮人之寵御。以次而進。若貫魚也。即五率群陰以承陽。魚貫而進也。詩邶風宴爾新婚。不我屑以。箋以用也。以宮人寵。即用宮人寵也。蒙之用說桎告（左木）。益之利用為依遷國。皆與此以字義同也。此與豫九四之朋盍谷簪。皆為易象之最神妙。而最難於形容者。王陶廬雲。易辭有非注視卦象不能解者。此等是也。而二千年來。因簪象魚象之失傳。遂改營為音（右戈）為攝。以求與坎象合。命剝五變巽。以求與魚象合。而易理遂亡於解說矣。杜甫雲。蓋簪喧櫪馬。鮑照雲。魚貫度飛樑。皆此二句之確詁。而杜詩尤非真知易者。不敢如此道也。宋蔡弼注社詩。遂誤為宴朋友。</p><h3 id="象曰。以宮人寵。終無尤也。" tabindex="-1">象曰。以宮人寵。終無尤也。 <a class="header-anchor" href="#象曰。以宮人寵。終無尤也。" aria-label="Permalink to “象曰。以宮人寵。終無尤也。”">​</a></h3><p>五得承陽。故無尤悔。</p><p>上九。碩果不食。君子得輿。小人剝廬。</p><p>艮為果瓜。碩大也。孤陽在上。故曰碩果。震為食。震覆故不食。震食象失傳。詳魚氏易詁卦一陽未消。陝（？）餘在上。是其義也。艮為君子。坤為大輿為載。艮在坤上。乘輿之象也。故曰得輿。坤為小人。艮為廬。候卦陰終消陽。故曰剝廬。君子得輿。由上視下取象。小人剝廬。由下視上取象。</p><h3 id="象曰。君子得輿。民所載也。小人剝廬。終不可用也。" tabindex="-1">象曰。君子得輿。民所載也。小人剝廬。終不可用也。 <a class="header-anchor" href="#象曰。君子得輿。民所載也。小人剝廬。終不可用也。" aria-label="Permalink to “象曰。君子得輿。民所載也。小人剝廬。終不可用也。”">​</a></h3><p>坤為民。艮為終。</p>',28)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
